    const angle = (index / 60) * Math.PI * 2 - Math.PI / 2;
    const cos = Math.cos(angle);
    const sin = Math.sin(angle);
    ctx.line(cx + cos * inner, cy + sin * inner, cx + cos * outer, cy + sin * outer, 2.5, index < lit ? color : "#ffffff1f");
